// Training Data từ MyDLL.md
const trainingData = {
  "training_data": [
    // ====================================================================
    // 1. DDL - Database Schemas
    // ====================================================================
    {
      "ddl": `CREATE TABLE customer (
    customer_id SERIAL PRIMARY KEY,
    customer_name TEXT NOT NULL,
    address TEXT,
    phone_number VARCHAR(20),
    debt NUMERIC(18,2) DEFAULT 0
);`
    },
    {
      "ddl": `CREATE TABLE product (
    product_id SERIAL PRIMARY KEY,
    product_name TEXT NOT NULL,
    stock_quantity INT DEFAULT 0,
    sale_price NUMERIC(18,2) NOT NULL,
    import_price NUMERIC(18,2) NOT NULL
);`
    },
    {
      "ddl": `CREATE TABLE employee (
    employee_id SERIAL PRIMARY KEY,
    employee_name TEXT NOT NULL,
    address TEXT,
    email TEXT,
    phone_number VARCHAR(20),
    department TEXT
);`
    },
    {
      "ddl": `CREATE TABLE sales_detail (
    sale_id SERIAL PRIMARY KEY,
    customer_id INT REFERENCES customer(customer_id),
    product_id INT REFERENCES product(product_id),
    sale_date DATE NOT NULL,
    sale_price NUMERIC(18,2) NOT NULL,
    employee_id INT REFERENCES employee(employee_id)
);`
    },

    // ====================================================================
    // 2. Documentation - Business Logic
    // ====================================================================
    {
      "documentation": `Bảng customer - Thông tin khách hàng:
- customer_id: Mã định danh duy nhất của khách hàng (Primary Key)
- customer_name: Tên hoặc tên tổ chức khách hàng
- address: Địa chỉ khách hàng
- phone_number: Số điện thoại liên hệ (VARCHAR 20 ký tự)
- debt: Số nợ hiện tại của khách hàng (VNĐ, mặc định 0)

Mối quan hệ: Liên kết 1:N với bảng sales_detail qua customer_id`
    },
    {
      "documentation": `Bảng product - Thông tin hàng hóa:
- product_id: Mã định danh duy nhất của sản phẩm (Primary Key)
- product_name: Tên sản phẩm (VD: Máy giặt LG 9kg)
- stock_quantity: Số lượng tồn kho hiện có
- sale_price: Giá bán ra cho khách hàng (VNĐ)
- import_price: Giá nhập hàng (VNĐ)

Mối quan hệ: Liên kết 1:N với bảng sales_detail qua product_id
Lưu ý: Lợi nhuận = sale_price - import_price`
    },
    {
      "documentation": `Bảng employee - Thông tin nhân viên:
- employee_id: Mã định danh duy nhất của nhân viên (Primary Key)
- employee_name: Tên nhân viên
- address: Địa chỉ nhân viên
- email: Địa chỉ email liên hệ
- phone_number: Số điện thoại
- department: Phòng ban (VD: Kinh doanh, Kế toán, Marketing)

Mối quan hệ: Liên kết 1:N với bảng sales_detail qua employee_id`
    },
    {
      "documentation": `Bảng sales_detail - Chi tiết giao dịch bán hàng (FACT TABLE):
- sale_id: Mã định danh duy nhất của giao dịch (Primary Key)
- customer_id: Mã khách hàng mua hàng (Foreign Key → customer)
- product_id: Mã sản phẩm được bán (Foreign Key → product)
- sale_date: Ngày diễn ra giao dịch
- sale_price: Giá bán thực tế trong giao dịch này (VNĐ)
- employee_id: Mã nhân viên thực hiện bán hàng (Foreign Key → employee)

Đây là bảng trung tâm (fact table) liên kết 3 bảng: customer, product, employee`
    },
    {
      "documentation": `Cấu trúc database (ERD):
customer (1) ───< sales_detail >───(1) product
                       │
                       │
                       v
                   employee

Mỗi khách hàng, sản phẩm và nhân viên đều có thể tham gia nhiều giao dịch trong bảng sales_detail.
Đây là mô hình Star Schema với sales_detail là fact table.`
    },
    {
      "documentation": `Lưu ý quan trọng khi viết SQL:
1. Bảng sales_detail là bảng trung tâm, thường cần JOIN với các bảng khác
2. Để tính doanh thu: SUM(sale_price) từ sales_detail
3. Để tính lợi nhuận: SUM(sale_price - import_price) cần JOIN với product
4. Ngày giao dịch được lưu trong trường sale_date (kiểu DATE)
5. Tất cả giá trị tiền tệ đều là NUMERIC(18,2) - đơn vị VNĐ
6. Tồn kho được quản lý trong product.stock_quantity`
    },
    {
      "documentation": `Best practices khi query:
1. JOIN customer để lấy tên khách hàng thay vì chỉ customer_id
2. JOIN product để lấy tên sản phẩm thay vì chỉ product_id
3. JOIN employee để lấy tên nhân viên thay vì chỉ employee_id
4. Sử dụng COALESCE(SUM(...), 0) để xử lý NULL khi không có dữ liệu
5. Format ngày tháng: TO_CHAR(sale_date, 'YYYY-MM-DD')
6. Filter theo năm: EXTRACT(YEAR FROM sale_date) = 2024
7. Filter theo tháng: EXTRACT(MONTH FROM sale_date) = 10`
    },

    // ====================================================================
    // 3. Question-SQL Pairs
    // ====================================================================

    // --- Khách hàng ---
    {
      "question": "Liệt kê tất cả khách hàng",
      "sql": "SELECT customer_id, customer_name, address, phone_number, debt FROM customer ORDER BY customer_name;"
    },
    {
      "question": "Top 10 khách hàng có doanh thu cao nhất",
      "sql": `SELECT 
    c.customer_name,
    SUM(sd.sale_price) as total_revenue
FROM customer c
JOIN sales_detail sd ON c.customer_id = sd.customer_id
GROUP BY c.customer_id, c.customer_name
ORDER BY total_revenue DESC
LIMIT 10;`
    },
    {
      "question": "Khách hàng nào đang nợ tiền?",
      "sql": "SELECT customer_name, debt FROM customer WHERE debt > 0 ORDER BY debt DESC;"
    },
    {
      "question": "Tổng số nợ của tất cả khách hàng",
      "sql": "SELECT COALESCE(SUM(debt), 0) as total_debt FROM customer;"
    },
    {
      "question": "Khách hàng mua nhiều sản phẩm nhất",
      "sql": `SELECT 
    c.customer_name,
    COUNT(sd.sale_id) as total_purchases
FROM customer c
JOIN sales_detail sd ON c.customer_id = sd.customer_id
GROUP BY c.customer_id, c.customer_name
ORDER BY total_purchases DESC
LIMIT 1;`
    },

    // --- Sản phẩm ---
    {
      "question": "Liệt kê tất cả sản phẩm",
      "sql": "SELECT product_id, product_name, stock_quantity, sale_price, import_price FROM product ORDER BY product_name;"
    },
    {
      "question": "Sản phẩm nào đang hết hàng?",
      "sql": "SELECT product_name, stock_quantity FROM product WHERE stock_quantity = 0 ORDER BY product_name;"
    },
    {
      "question": "Sản phẩm nào có tồn kho ít hơn 10?",
      "sql": "SELECT product_name, stock_quantity FROM product WHERE stock_quantity < 10 ORDER BY stock_quantity;"
    },
    {
      "question": "Top 5 sản phẩm bán chạy nhất",
      "sql": `SELECT 
    p.product_name,
    COUNT(sd.sale_id) as total_sales
FROM product p
JOIN sales_detail sd ON p.product_id = sd.product_id
GROUP BY p.product_id, p.product_name
ORDER BY total_sales DESC
LIMIT 5;`
    },
    {
      "question": "Sản phẩm nào có lợi nhuận cao nhất?",
      "sql": `SELECT 
    p.product_name,
    (p.sale_price - p.import_price) as profit_per_unit,
    p.sale_price,
    p.import_price
FROM product p
ORDER BY profit_per_unit DESC
LIMIT 1;`
    },
    {
      "question": "Tổng giá trị hàng tồn kho",
      "sql": "SELECT SUM(stock_quantity * import_price) as total_inventory_value FROM product;"
    },

    // --- Nhân viên ---
    {
      "question": "Liệt kê tất cả nhân viên",
      "sql": "SELECT employee_id, employee_name, department, email, phone_number FROM employee ORDER BY employee_name;"
    },
    {
      "question": "Nhân viên nào bán được nhiều đơn hàng nhất?",
      "sql": `SELECT 
    e.employee_name,
    e.department,
    COUNT(sd.sale_id) as total_sales
FROM employee e
JOIN sales_detail sd ON e.employee_id = sd.employee_id
GROUP BY e.employee_id, e.employee_name, e.department
ORDER BY total_sales DESC
LIMIT 1;`
    },
    {
      "question": "Top 10 nhân viên theo doanh thu",
      "sql": `SELECT 
    e.employee_name,
    e.department,
    SUM(sd.sale_price) as total_revenue
FROM employee e
JOIN sales_detail sd ON e.employee_id = sd.employee_id
GROUP BY e.employee_id, e.employee_name, e.department
ORDER BY total_revenue DESC
LIMIT 10;`
    },
    {
      "question": "Có bao nhiêu nhân viên trong mỗi phòng ban?",
      "sql": "SELECT department, COUNT(*) as employee_count FROM employee GROUP BY department ORDER BY employee_count DESC;"
    },
    {
      "question": "Danh sách email phòng kinh doanh",
      "sql": "select * from employee where department ILIKE ('%kinh doanh%'); loại bỏ chữ 'phòng' hoặc 'phòng ban' trong điều kiện lọc"
    },
    {
      "question": "Xem email của nhân viên nguyễn văn a",
      "sql": "select * from employee where employee_name ILIKE ('%nguyễn văn a%');"
    },

    // --- Giao dịch ---
    {
      "question": "Tổng doanh thu là bao nhiêu?",
      "sql": "SELECT COALESCE(SUM(sale_price), 0) as total_revenue FROM sales_detail;"
    },
    {
      "question": "Có bao nhiêu giao dịch trong hệ thống?",
      "sql": "SELECT COUNT(*) as total_transactions FROM sales_detail;"
    },
    {
      "question": "Doanh thu theo từng tháng trong năm 2024",
      "sql": `SELECT 
    EXTRACT(MONTH FROM sale_date) as month,
    SUM(sale_price) as monthly_revenue
FROM sales_detail
WHERE EXTRACT(YEAR FROM sale_date) = 2024
GROUP BY month
ORDER BY month;`
    },
    {
      "question": "Doanh thu hôm nay",
      "sql": "SELECT COALESCE(SUM(sale_price), 0) as today_revenue FROM sales_detail WHERE sale_date = CURRENT_DATE;"
    },
    {
      "question": "Doanh thu tháng này",
      "sql": `SELECT COALESCE(SUM(sale_price), 0) as month_revenue 
FROM sales_detail 
WHERE EXTRACT(YEAR FROM sale_date) = EXTRACT(YEAR FROM CURRENT_DATE)
AND EXTRACT(MONTH FROM sale_date) = EXTRACT(MONTH FROM CURRENT_DATE);`
    },
    {
      "question": "Doanh thu năm nay",
      "sql": `SELECT COALESCE(SUM(sale_price), 0) as year_revenue 
FROM sales_detail 
WHERE EXTRACT(YEAR FROM sale_date) = EXTRACT(YEAR FROM CURRENT_DATE);`
    },
    {
      "question": "10 giao dịch gần nhất",
      "sql": `SELECT 
    sd.sale_id,
    c.customer_name,
    p.product_name,
    sd.sale_price,
    sd.sale_date,
    e.employee_name
FROM sales_detail sd
JOIN customer c ON sd.customer_id = c.customer_id
JOIN product p ON sd.product_id = p.product_id
JOIN employee e ON sd.employee_id = e.employee_id
ORDER BY sd.sale_date DESC, sd.sale_id DESC
LIMIT 10;`
    },
    {
      "question": "Tổng lợi nhuận từ tất cả giao dịch",
      "sql": `SELECT 
    SUM(sd.sale_price - p.import_price) as total_profit
FROM sales_detail sd
JOIN product p ON sd.product_id = p.product_id;`
    },
    {
      "question": "Doanh thu và lợi nhuận theo sản phẩm",
      "sql": `SELECT 
    p.product_name,
    COUNT(sd.sale_id) as total_sales,
    SUM(sd.sale_price) as total_revenue,
    SUM(sd.sale_price - p.import_price) as total_profit
FROM product p
JOIN sales_detail sd ON p.product_id = sd.product_id
GROUP BY p.product_id, p.product_name
ORDER BY total_revenue DESC;`
    },

    // --- Queries phức tạp ---
    {
      "question": "Phân tích doanh thu theo khách hàng và sản phẩm",
      "sql": `SELECT 
    c.customer_name,
    p.product_name,
    COUNT(sd.sale_id) as purchase_count,
    SUM(sd.sale_price) as total_spent
FROM sales_detail sd
JOIN customer c ON sd.customer_id = c.customer_id
JOIN product p ON sd.product_id = p.product_id
GROUP BY c.customer_id, c.customer_name, p.product_id, p.product_name
ORDER BY total_spent DESC
LIMIT 20;`
    },
    {
      "question": "Top 5 ngày có doanh thu cao nhất",
      "sql": `SELECT 
    sale_date,
    COUNT(sale_id) as transaction_count,
    SUM(sale_price) as daily_revenue
FROM sales_detail
GROUP BY sale_date
ORDER BY daily_revenue DESC
LIMIT 5;`
    },
    {
      "question": "Tỉ lệ lợi nhuận trung bình theo sản phẩm",
      "sql": `SELECT 
    p.product_name,
    AVG((sd.sale_price - p.import_price) / NULLIF(p.import_price, 0) * 100) as avg_profit_margin
FROM product p
JOIN sales_detail sd ON p.product_id = sd.product_id
GROUP BY p.product_id, p.product_name
ORDER BY avg_profit_margin DESC;`
    },
    {
      "question": "Hiệu suất bán hàng theo phòng ban",
      "sql": `SELECT 
    e.department,
    COUNT(DISTINCT e.employee_id) as employee_count,
    COUNT(sd.sale_id) as total_sales,
    SUM(sd.sale_price) as total_revenue
FROM employee e
JOIN sales_detail sd ON e.employee_id = sd.employee_id
GROUP BY e.department
ORDER BY total_revenue DESC;`
    }
  ]
};

